(31704, 'Numbers 6:8', 'Numbers', 6, 8, 'ترڅو پورې چې هغه نذر ورکوي، هغه به څښتن ته وقف وي.', 'ترچو پورې چې هغه نذر ورکوی، هغه به چشتن ته وقف وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31705, 'Numbers 6:9', 'Numbers', 6, 9, 'که چېرې د هغه وقف شوي ویښتان یو چاته په ورنژدې کېدلو سره چې ناڅاپه مړ شي ناپاک شي، هغه باید اووه ورځې صبر وکړي او بیا خپل سر وخرایي، نو هغه به په مذهبي لحاظ پاک شي.', 'که چېرې د هغه وقف شوی ویشتان یو چاته په ورنژدې کېدلو سره چې ناچاپه مر شی ناپاک شی، هغه باید اووه ورجې صبر وکری او بیا خپل سر وخرایی، نو هغه به په مذهبی لحاظ پاک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31706, 'Numbers 6:10', 'Numbers', 6, 10, 'په اتمه ورځ به هغه کس دوه کوترې یا دوه قمري ګانې د سپېڅلې خېمې دروازې ته کاهن ته راوړي.', 'په اتمه ورج به هغه کس دوه کوترې یا دوه قمری ګانې د سپېچلې خېمې دروازې ته کاهن ته راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31707, 'Numbers 6:11', 'Numbers', 6, 11, 'کاهن به یوه مرغۍ د ګناه د نذرانې په توګه او بله به د سوځېدونکې نذرانې په توګه وړاندې کړي چې د هغه دپاره کفاره ادا کړي، ځکه چې هغه مړي ته په ورنژدې کېدلو سره ګناه کړې ده. هغه دې په هماغه ورځ د خپلو ویښتانو د پاکولو مراسم تر سره کړي.', 'کاهن به یوه مرغی د ګناه د نذرانې په توګه او بله به د سوجېدونکې نذرانې په توګه وراندې کری چې د هغه دپاره کفاره ادا کری، جکه چې هغه مری ته په ورنژدې کېدلو سره ګناه کرې ده. هغه دې په هماغه ورج د خپلو ویشتانو د پاکولو مراسم تر سره کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31708, 'Numbers 6:12', 'Numbers', 6, 12, 'نو هغه کس دې خپل وخت بیا څښتن ته وقف کړي. تېرې شوې ورځې نه حسابیږي، ځکه چې د هغه سپېڅلي ویښتان ناپاکه شول. هغه باید د تاوان د نذرانې په توګه یو وری چې یو کلن وي راوړي.', 'نو هغه کس دې خپل وخت بیا چشتن ته وقف کری. تېرې شوې ورجې نه حسابیزی، جکه چې د هغه سپېچلی ویشتان ناپاکه شول. هغه باید د تاوان د نذرانې په توګه یو وری چې یو کلن وی راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31709, 'Numbers 6:13', 'Numbers', 6, 13, 'کله چې هغه کس خپله هغه موده پوره کړي چې هغه په کې دا وعده کړې ده چې نذر به ورکوي، باید دا مراسم سرته ورسوي. د سپېڅلې خېمې دروازې ته دې ورشي', 'کله چې هغه کس خپله هغه موده پوره کری چې هغه په کې دا وعده کرې ده چې نذر به ورکوی، باید دا مراسم سرته ورسوی. د سپېچلې خېمې دروازې ته دې ورشی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31710, 'Numbers 6:14', 'Numbers', 6, 14, 'او څښتن ته دې درې داسې حیوانات وړاندې کړي چې کوم عیب په کې نه وي، یعنې یو وری چې یو کلن وي د سوځېدونکې نذرانې دپاره، یوه یو کلنه مېږه د ګناه د نذرانې دپاره او یو پسه د سلامتۍ د نذرانې دپاره.', 'او چشتن ته دې درې داسې حیوانات وراندې کری چې کوم عیب په کې نه وی، یعنې یو وری چې یو کلن وی د سوجېدونکې نذرانې دپاره، یوه یو کلنه مېزه د ګناه د نذرانې دپاره او یو پسه د سلامتی د نذرانې دپاره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31711, 'Numbers 6:15', 'Numbers', 6, 15, 'هغه دې یوه ټوکرۍ فطیره ډوډۍ هم وړاندې کړي یعنې پنډې ډوډۍ چې د داسې ښو اوړو څخه تیارې شوې وي چې د زیتونو تېل ورسره ګډ وي او داسې نرۍ ډوډۍ چې تېل ورباندې موښل شوي وي او د غلې دانې او د څښلو نذرانې هم باید ورسره وي.', 'هغه دې یوه توکری فطیره دودی هم وراندې کری یعنې پندې دودی چې د داسې شو اورو چخه تیارې شوې وی چې د زیتونو تېل ورسره ګد وی او داسې نری دودی چې تېل ورباندې موشل شوی وی او د غلې دانې او د چشلو نذرانې هم باید ورسره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_6_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
